"use client";

import { useTransition } from "react";
import { useTranslation } from "react-i18next";
import { Loader2 } from "lucide-react";
import { downloadMyDataAction } from "@/app/(app)/account/settings/profile/actions";
import { Badge } from "@/modules/ui/components/badge";
import { Button } from "@/modules/ui/components/button";
import { H4, Small } from "@/modules/ui/components/typography";

export const DownloadMyData = () => {
  const { t } = useTranslation();
  const [isPending, startTransition] = useTransition();

  const handleDownload = () => {
    startTransition(async () => {
      const result = await downloadMyDataAction();
      if (result.data) {
        const blob = new Blob([JSON.stringify(result.data, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = "formbricks-account-data.json";
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }
    });
  };

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center gap-x-4">
        <div className="flex flex-col">
          <Small color="muted">{t("workspace.settings.profile.download_my_data_description")}</Small>
          <div className="mt-2 flex items-center gap-x-2">
            <Badge size="normal" type="warning" text="Beta" />
          </div>
        </div>
      </div>
      <Button onClick={handleDownload} disabled={isPending} variant="secondary">
        {isPending ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" />
            {t("workspace.settings.profile.download_my_data_button")}
          </>
        ) : (
          t("workspace.settings.profile.download_my_data_button")
        )}
      </Button>
    </div>
  );
};

"use server";

import { prisma } from "@formbricks/database";
import { AuthenticationError } from "@formbricks/types/errors";
import { getUser } from "@/lib/user/service";
import { authenticatedActionClient } from "@/lib/utils/action-client";

export const downloadMyDataAction = authenticatedActionClient.action(async ({ ctx }) => {
  const user = await getUser(ctx.user.id);
  if (!user) {
    throw new AuthenticationError("User not found");
  }

  const memberships = await prisma.membership.findMany({
    where: {
      userId: ctx.user.id,
    },
    select: {
      organization: {
        select: {
          name: true,
        },
      },
      role: true,
    },
  });

  return {
    name: user.name,
    email: user.email,
    locale: user.locale ?? null,
    notificationSettings: user.notificationSettings ?? {},
    organizationMemberships: memberships.map((m) => ({
      organizationName: m.organization.name,
      role: m.role,
    })),
  };
});

