const badRequest = (
  log: ReturnType<typeof logger.withContext>,
  requestId: string,
  instance: string,
  invalidParams: TV3InvalidParam[]
): Response => {
  log.warn({ statusCode: 400, invalidParams }, "Validation failed");
  return problemBadRequest(requestId, "Invalid query parameters", {
